beforeExample:
import java.io.InputStream;
import java.io.StringBufferInputStream; // Deprecated

public class TestClass {
    public InputStream createStream(String contents) {
        return new StringBufferInputStream(contents);
    }
}

afterExample:
import java.io.InputStream;
import java.io.ByteArrayInputStream;

public class TestClass {
    public InputStream createStream(String contents) {
        return new ByteArrayInputStream(contents.getBytes());
    }
}

negativeExample:
import java.io.InputStream;
import java.io.ByteArrayInputStream;

public class TestClass {
    public InputStream createStream(byte[] data) {
        return new ByteArrayInputStream(data); // Should not match
    }
}
